CREATE TABLE ty_hr_field_definition(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),code text NOT NULL,label text NOT NULL,
 field_type text NOT NULL CHECK(field_type IN('text','date','number','select','boolean')),sensitivity text NOT NULL CHECK(sensitivity IN('normal','restricted')),
 options jsonb NOT NULL DEFAULT '[]',required boolean NOT NULL DEFAULT false,status text NOT NULL DEFAULT 'active'CHECK(status IN('active','inactive')),
 revision integer NOT NULL DEFAULT 1,created_by bigint NOT NULL REFERENCES sys_account(id),UNIQUE(group_id,code)
);
CREATE TABLE ty_hr_person_profile(
 person_id bigint PRIMARY KEY,group_id bigint NOT NULL,owner_company_id bigint REFERENCES ty_company(id),
 public_values jsonb NOT NULL DEFAULT '{}',private_cipher text,private_iv text,private_tag text,private_revision integer NOT NULL DEFAULT 0,
 revision integer NOT NULL DEFAULT 1,created_by bigint NOT NULL REFERENCES sys_account(id),updated_by bigint NOT NULL REFERENCES sys_account(id),updated_at timestamptz NOT NULL DEFAULT now(),
 FOREIGN KEY(person_id,group_id)REFERENCES ty_person(id,group_id),CHECK(num_nonnulls(private_cipher,private_iv,private_tag)IN(0,3))
);
CREATE TABLE ty_hr_person_alias(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL,person_id bigint NOT NULL,alias_kind text NOT NULL CHECK(alias_kind IN('previous_name','external_employee_number','source_name')),
 namespace text NOT NULL,alias_text text NOT NULL,source_ref text NOT NULL,created_by bigint NOT NULL REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now(),
 FOREIGN KEY(person_id,group_id)REFERENCES ty_person(id,group_id),UNIQUE(group_id,person_id,alias_kind,namespace,alias_text)
);
CREATE TABLE ty_hr_profile_history(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),person_id bigint NOT NULL REFERENCES ty_person(id),
 revision integer NOT NULL,changed_fields text[] NOT NULL,actor_id bigint NOT NULL REFERENCES sys_account(id),reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(person_id,revision)
);
CREATE TABLE ty_hr_number_rule(
 group_id bigint PRIMARY KEY REFERENCES ty_group(id),prefix text NOT NULL DEFAULT 'TY'CHECK(prefix~'^[A-Za-z][A-Za-z0-9-]{0,15}$'),padding integer NOT NULL DEFAULT 6 CHECK(padding BETWEEN 3 AND 16),
 allow_manual boolean NOT NULL DEFAULT true,revision integer NOT NULL DEFAULT 1,updated_by bigint NOT NULL REFERENCES sys_account(id)
);
CREATE TABLE ty_hr_assignment_fte(
 assignment_id bigint PRIMARY KEY REFERENCES ty_position_assignment(id),fte numeric(8,4) NOT NULL CHECK(fte>0 AND fte<=1),counts_in_headcount boolean NOT NULL DEFAULT true,
 revision integer NOT NULL DEFAULT 1,updated_by bigint NOT NULL REFERENCES sys_account(id)
);
CREATE TABLE ty_hr_org_revision(
 entity_kind text NOT NULL CHECK(entity_kind IN('group','brand','ledger','company','department','work_area','job','grade','position')),
 entity_id bigint NOT NULL,revision integer NOT NULL DEFAULT 1,updated_by bigint NOT NULL REFERENCES sys_account(id),updated_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(entity_kind,entity_id)
);
CREATE TABLE ty_hr_headcount_plan(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),
 scope_kind text NOT NULL CHECK(scope_kind IN('company','department','position')),department_id bigint REFERENCES ty_department(id),position_id bigint REFERENCES ty_company_position(id),
 code text NOT NULL,version integer NOT NULL,valid_from date NOT NULL,valid_to date,budget_count integer NOT NULL CHECK(budget_count>=0),budget_fte numeric(12,4)CHECK(budget_fte>=0),
 status text NOT NULL DEFAULT 'draft'CHECK(status IN('draft','published','retired')),revision integer NOT NULL DEFAULT 1,created_by bigint NOT NULL REFERENCES sys_account(id),published_by bigint REFERENCES sys_account(id),published_at timestamptz,
 CHECK(valid_to IS NULL OR valid_to>valid_from),CHECK((scope_kind='company'AND department_id IS NULL AND position_id IS NULL)OR(scope_kind='department'AND department_id IS NOT NULL AND position_id IS NULL)OR(scope_kind='position'AND department_id IS NOT NULL AND position_id IS NOT NULL)),
 CHECK(status<>'published'OR(published_by IS NOT NULL AND published_at IS NOT NULL)),UNIQUE(company_id,code,version)
);
CREATE TABLE ty_hr_change_request(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),person_id bigint REFERENCES ty_person(id),employment_id bigint REFERENCES ty_employment(id),
 action text NOT NULL CHECK(action IN('onboard','rehire','confirm_probation','transfer','leave','promote','assign','secondment')),
 effective_date date NOT NULL,payload jsonb NOT NULL,source_snapshot jsonb NOT NULL,source_hash text NOT NULL,
 status text NOT NULL DEFAULT 'pending'CHECK(status IN('pending','approved','rejected','cancelled')),execution_state text NOT NULL DEFAULT 'pending'CHECK(execution_state IN('pending','applied','blocked','not_applicable')),
 revision integer NOT NULL DEFAULT 1,created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),executed_by bigint REFERENCES sys_account(id),
 workflow_instance_id bigint REFERENCES ty_workflow_instance(id),decision_reason text,created_at timestamptz NOT NULL DEFAULT now(),applied_at timestamptz,result jsonb
);
CREATE TABLE ty_hr_employment_detail(
 employment_id bigint PRIMARY KEY REFERENCES ty_employment(id),probation_end_on date,confirmed_on date,confirmation_ref text,
 revision integer NOT NULL DEFAULT 1,updated_by bigint NOT NULL REFERENCES sys_account(id)
);
CREATE TABLE ty_hr_secondment(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,request_id bigint NOT NULL UNIQUE REFERENCES ty_hr_change_request(id),
 group_id bigint NOT NULL REFERENCES ty_group(id),person_id bigint NOT NULL REFERENCES ty_person(id),employment_id bigint NOT NULL REFERENCES ty_employment(id),
 company_id bigint NOT NULL REFERENCES ty_company(id),receiving_company_id bigint NOT NULL REFERENCES ty_company(id),department_id bigint NOT NULL REFERENCES ty_department(id),work_area_id bigint REFERENCES ty_work_area(id),
 valid_from date NOT NULL,valid_to date NOT NULL,cost_basis_ref text NOT NULL,created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint NOT NULL REFERENCES sys_account(id),
 CHECK(valid_to>valid_from),CHECK(company_id<>receiving_company_id)
);
CREATE TABLE ty_hr_file_asset(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint REFERENCES ty_company(id),person_id bigint REFERENCES ty_person(id),
 owner_kind text NOT NULL CHECK(owner_kind IN('person','candidate','contract','certificate','workflow','training','performance','import')),
 owner_id bigint,filename text NOT NULL,mime text NOT NULL,byte_length integer NOT NULL CHECK(byte_length BETWEEN 1 AND 8388608),sha256 text NOT NULL,
 sensitivity text NOT NULL CHECK(sensitivity IN('normal','restricted')),content bytea NOT NULL,content_iv text,content_tag text,storage_encoding text NOT NULL DEFAULT 'aes256gcm'CHECK(storage_encoding IN('plain','aes256gcm')),
 created_by bigint NOT NULL REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now(),
 CHECK(octet_length(content)=byte_length),CHECK((storage_encoding='plain'AND content_iv IS NULL AND content_tag IS NULL)OR(storage_encoding='aes256gcm'AND content_iv IS NOT NULL AND content_tag IS NOT NULL)),CHECK(sensitivity<>'restricted'OR storage_encoding='aes256gcm'),UNIQUE(group_id,owner_kind,owner_id,sha256)
);
CREATE TABLE ty_hr_requisition(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),
 department_id bigint NOT NULL REFERENCES ty_department(id),position_id bigint NOT NULL REFERENCES ty_company_position(id),headcount_plan_id bigint REFERENCES ty_hr_headcount_plan(id),
 code text NOT NULL,title text NOT NULL,quantity integer NOT NULL CHECK(quantity>0),target_on date,reason text NOT NULL,requirements jsonb NOT NULL DEFAULT '{}',
 status text NOT NULL DEFAULT 'draft'CHECK(status IN('draft','pending','approved','rejected','closed','cancelled')),revision integer NOT NULL DEFAULT 1,created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(group_id,code)
);
CREATE TABLE ty_hr_candidate(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),requisition_id bigint NOT NULL REFERENCES ty_hr_requisition(id),
 code text NOT NULL,full_name text NOT NULL,contact_cipher text,contact_iv text,contact_tag text,contact_revision integer NOT NULL DEFAULT 0,
 resume_file_id bigint REFERENCES ty_hr_file_asset(id),source_channel text NOT NULL,source_ref text,linked_person_id bigint REFERENCES ty_person(id),
 status text NOT NULL DEFAULT 'new'CHECK(status IN('new','screening','interview','offered','accepted','rejected','withdrawn','hired')),revision integer NOT NULL DEFAULT 1,
 resume_reviewed_by bigint REFERENCES sys_account(id),resume_reviewed_at timestamptz,resume_review_ref text,reviewed_resume_sha256 text,
 created_by bigint NOT NULL REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(group_id,code),CHECK(num_nonnulls(contact_cipher,contact_iv,contact_tag)IN(0,3))
);
CREATE TABLE ty_hr_interview(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,candidate_id bigint NOT NULL REFERENCES ty_hr_candidate(id),round_no integer NOT NULL CHECK(round_no>0),
 interviewer_id bigint NOT NULL REFERENCES sys_account(id),scheduled_at timestamptz NOT NULL,score numeric(8,2),decision text CHECK(decision IN('pass','hold','reject')),notes text,
 status text NOT NULL DEFAULT 'scheduled'CHECK(status IN('scheduled','completed','cancelled')),revision integer NOT NULL DEFAULT 1,created_by bigint NOT NULL REFERENCES sys_account(id),UNIQUE(candidate_id,round_no)
);
CREATE TABLE ty_hr_offer(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,candidate_id bigint NOT NULL REFERENCES ty_hr_candidate(id),version integer NOT NULL,starts_on date NOT NULL,terms jsonb NOT NULL,
 salary_cipher text,salary_iv text,salary_tag text,source_hash text NOT NULL,status text NOT NULL DEFAULT 'draft'CHECK(status IN('draft','pending','approved','sent','accepted','declined','withdrawn','hired')),
 revision integer NOT NULL DEFAULT 1,created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),sent_evidence_ref text,sent_at timestamptz,accepted_evidence_ref text,accepted_by bigint REFERENCES sys_account(id),accepted_at timestamptz,
 resulting_person_id bigint REFERENCES ty_person(id),resulting_employment_id bigint REFERENCES ty_employment(id),UNIQUE(candidate_id,version),CHECK(num_nonnulls(salary_cipher,salary_iv,salary_tag)IN(0,3))
);
CREATE TABLE ty_hr_contract(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),person_id bigint NOT NULL REFERENCES ty_person(id),employment_id bigint NOT NULL REFERENCES ty_employment(id),legal_entity_company_id bigint NOT NULL REFERENCES ty_company(id),
 region_code text NOT NULL CHECK(region_code IN('CN','HK')),code text NOT NULL,version integer NOT NULL,status text NOT NULL DEFAULT 'draft'CHECK(status IN('draft','signed','terminated','cancelled')),
 parent_contract_id bigint REFERENCES ty_hr_contract(id),parent_key text NOT NULL,starts_on date NOT NULL,ends_on date,signed_on date,
 revision integer NOT NULL DEFAULT 1,created_by bigint NOT NULL REFERENCES sys_account(id),signed_by bigint REFERENCES sys_account(id),evidence_file_id bigint REFERENCES ty_hr_file_asset(id),source_hash text NOT NULL,terminated_on date,termination_ref text,terminated_by bigint REFERENCES sys_account(id),
 title text NOT NULL,content jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK(ends_on IS NULL OR ends_on>=starts_on),CHECK(status NOT IN('signed','terminated')OR(signed_on IS NOT NULL AND signed_by IS NOT NULL AND evidence_file_id IS NOT NULL)),CHECK(status<>'terminated'OR(terminated_on IS NOT NULL AND terminated_on>=starts_on AND termination_ref IS NOT NULL AND terminated_by IS NOT NULL)),UNIQUE(group_id,code,version)
);
CREATE TABLE ty_hr_contract_term(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,contract_id bigint NOT NULL REFERENCES ty_hr_contract(id),term_code text NOT NULL,term_kind text NOT NULL CHECK(term_kind IN('salary','bonus','attendance','job','other')),
 payroll_item_code text REFERENCES ty_pay_item_catalog(code),amount numeric(20,4),currency text CHECK(currency IN('CNY','HKD')),unit text,value jsonb NOT NULL,
 valid_from date NOT NULL,valid_to date,status text NOT NULL DEFAULT 'draft'CHECK(status IN('draft','reviewed','effective','ended')),revision integer NOT NULL DEFAULT 1,
 created_by bigint NOT NULL REFERENCES sys_account(id),reviewed_by bigint REFERENCES sys_account(id),applied_by bigint REFERENCES sys_account(id),parent_key text NOT NULL,source_hash text NOT NULL,
 CHECK(valid_to IS NULL OR valid_to>valid_from),CHECK(amount IS NULL OR amount>=0),CHECK((amount IS NULL)OR(currency IS NOT NULL AND unit IS NOT NULL)),UNIQUE(contract_id,term_code)
);
CREATE TABLE ty_hr_contract_term_period(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,term_id bigint NOT NULL REFERENCES ty_hr_contract_term(id),parent_key text NOT NULL,
 valid_from date NOT NULL,valid_to date,activated_by bigint NOT NULL REFERENCES sys_account(id),ended_by bigint REFERENCES sys_account(id),source_contract_id bigint NOT NULL REFERENCES ty_hr_contract(id),
 status text NOT NULL DEFAULT 'active' CHECK(status IN('active','cancelled')),cancellation_ref text,
 CHECK(valid_to IS NULL OR valid_to>valid_from),CHECK(status<>'cancelled'OR(ended_by IS NOT NULL AND length(btrim(cancellation_ref))>=4)),EXCLUDE USING gist(parent_key WITH=,daterange(valid_from,valid_to,'[)')WITH&&)WHERE(status='active')
);
CREATE TABLE ty_hr_reminder_rule(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint REFERENCES ty_company(id),kind text NOT NULL CHECK(kind IN('contract_expiry','probation','birthday','identity_expiry','onboarding')),
 lead_days integer NOT NULL CHECK(lead_days BETWEEN 0 AND 365),recipient_role text NOT NULL,channels text[] NOT NULL DEFAULT ARRAY['inbox']::text[],status text NOT NULL DEFAULT 'active'CHECK(status IN('active','inactive')),
 revision integer NOT NULL DEFAULT 1,created_by bigint NOT NULL REFERENCES sys_account(id),UNIQUE(group_id,company_id,kind,lead_days,recipient_role)
);
CREATE TABLE ty_hr_reminder(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),person_id bigint REFERENCES ty_person(id),
 kind text NOT NULL,source_key text NOT NULL,event_on date NOT NULL,recipient_id bigint NOT NULL REFERENCES sys_account(id),title text NOT NULL,
 state text NOT NULL DEFAULT 'open'CHECK(state IN('open','done','cancelled')),seen_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(source_key,recipient_id)
);
CREATE TABLE ty_hr_import_preview(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),
 namespace text NOT NULL,filename text NOT NULL,sha256 text NOT NULL,mapping jsonb NOT NULL,source_hash text NOT NULL,
 plan_cipher text NOT NULL,plan_iv text NOT NULL,plan_tag text NOT NULL,source_content bytea NOT NULL,source_iv text NOT NULL,source_tag text NOT NULL,
 row_count integer NOT NULL CHECK(row_count BETWEEN 1 AND 500),status text NOT NULL DEFAULT 'preview'CHECK(status IN('preview','committed')),revision integer NOT NULL DEFAULT 1,
 created_by bigint NOT NULL REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now(),committed_at timestamptz,
 UNIQUE(group_id,namespace,sha256,source_hash)
);

CREATE FUNCTION fn_ty_hr_scope_guard() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
DECLARE j jsonb:=to_jsonb(NEW);g bigint:=(j->>'group_id')::bigint;c bigint:=(j->>'company_id')::bigint;p bigint:=(j->>'person_id')::bigint;d bigint:=(j->>'department_id')::bigint;pos bigint:=(j->>'position_id')::bigint;e bigint:=(j->>'employment_id')::bigint;emp public.ty_employment;owner_company bigint:=(j->>'owner_company_id')::bigint;
BEGIN
 IF c IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_company WHERE id=c AND group_id=g)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='公司不属于当前集团';END IF;
 IF p IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_person WHERE id=p AND group_id=g)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='人员不属于当前集团';END IF;
 IF owner_company IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_company WHERE id=owner_company AND group_id=g)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='待入职资料公司不属于集团';END IF;
 IF d IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_department WHERE id=d AND company_id=c)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='部门不属于当前公司';END IF;
 IF pos IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_company_position WHERE id=pos AND company_id=c AND(d IS NULL OR department_id=d))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='岗位、部门与公司不一致';END IF;
 IF e IS NOT NULL THEN SELECT * INTO emp FROM public.ty_employment WHERE id=e;IF emp.id IS NULL OR emp.group_id<>g OR emp.company_id<>c OR emp.person_id<>p THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='人员、雇佣与公司不一致';END IF;END IF;
 IF TG_OP='UPDATE'AND(j->>'group_id')IS DISTINCT FROM(to_jsonb(OLD)->>'group_id')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='现有记录不可搬到其他集团';END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_hr_profile_scope BEFORE INSERT OR UPDATE ON ty_hr_person_profile FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_scope_guard();
CREATE TRIGGER ty_hr_alias_scope BEFORE INSERT OR UPDATE ON ty_hr_person_alias FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_scope_guard();
CREATE TRIGGER ty_hr_headcount_scope BEFORE INSERT OR UPDATE ON ty_hr_headcount_plan FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_scope_guard();
CREATE TRIGGER ty_hr_change_scope BEFORE INSERT OR UPDATE ON ty_hr_change_request FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_scope_guard();
CREATE TRIGGER ty_hr_file_scope BEFORE INSERT OR UPDATE ON ty_hr_file_asset FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_scope_guard();
CREATE TRIGGER ty_hr_requisition_scope BEFORE INSERT OR UPDATE ON ty_hr_requisition FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_scope_guard();
CREATE TRIGGER ty_hr_candidate_scope BEFORE INSERT OR UPDATE ON ty_hr_candidate FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_scope_guard();
CREATE TRIGGER ty_hr_contract_scope BEFORE INSERT OR UPDATE ON ty_hr_contract FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_scope_guard();
CREATE TRIGGER ty_hr_reminder_rule_scope BEFORE INSERT OR UPDATE ON ty_hr_reminder_rule FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_scope_guard();
CREATE TRIGGER ty_hr_reminder_scope BEFORE INSERT OR UPDATE ON ty_hr_reminder FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_scope_guard();
CREATE FUNCTION fn_ty_hr_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
BEGIN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='人员别名、附件与变更轨迹须保留，不能覆盖或删除';END;$$;
CREATE TRIGGER ty_hr_alias_keep BEFORE UPDATE OR DELETE ON ty_hr_person_alias FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_immutable();
CREATE TRIGGER ty_hr_profile_history_keep BEFORE UPDATE OR DELETE ON ty_hr_profile_history FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_immutable();
CREATE TRIGGER ty_hr_file_keep BEFORE UPDATE OR DELETE ON ty_hr_file_asset FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_immutable();
CREATE FUNCTION fn_ty_hr_version_guard() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='版本与业务历史不能删除';END IF;
 IF TG_TABLE_NAME='ty_hr_headcount_plan'AND OLD.status IN('published','retired')AND((to_jsonb(NEW)-ARRAY['status','revision'])<>(to_jsonb(OLD)-ARRAY['status','revision'])OR NEW.status NOT IN('published','retired')OR OLD.status='retired'AND NEW.status<>'retired')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已发布编制不能覆盖，另建版本';END IF;
 IF TG_TABLE_NAME='ty_hr_contract'AND OLD.status IN('signed','terminated','cancelled')AND((to_jsonb(NEW)-ARRAY['status','revision','terminated_on','termination_ref','terminated_by'])<>(to_jsonb(OLD)-ARRAY['status','revision','terminated_on','termination_ref','terminated_by'])OR OLD.status='signed'AND NEW.status NOT IN('signed','terminated')OR OLD.status IN('terminated','cancelled')AND(to_jsonb(NEW)-'revision')<>(to_jsonb(OLD)-'revision'))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已签合同不可覆盖，请续签或另建变更协议';END IF;
 IF TG_TABLE_NAME='ty_hr_contract_term'AND OLD.status IN('reviewed','effective','ended')AND((to_jsonb(NEW)-ARRAY['status','revision','applied_by'])<>(to_jsonb(OLD)-ARRAY['status','revision','applied_by'])OR NEW.status NOT IN('reviewed','effective','ended')OR OLD.status='effective'AND NEW.status='reviewed'OR OLD.status='ended'AND NEW.status<>'ended')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已核条款不可改写，另建合同版本';END IF;
 IF TG_TABLE_NAME='ty_hr_change_request'AND OLD.status<>'pending'AND(to_jsonb(NEW)-ARRAY['execution_state','executed_by','applied_at','result','revision'])<>(to_jsonb(OLD)-ARRAY['execution_state','executed_by','applied_at','result','revision'])THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已处理异动意图不可改写';END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_hr_headcount_version BEFORE UPDATE OR DELETE ON ty_hr_headcount_plan FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_version_guard();
CREATE TRIGGER ty_hr_contract_version BEFORE UPDATE OR DELETE ON ty_hr_contract FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_version_guard();
CREATE TRIGGER ty_hr_contract_term_version BEFORE UPDATE OR DELETE ON ty_hr_contract_term FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_version_guard();
CREATE TRIGGER ty_hr_change_version BEFORE UPDATE OR DELETE ON ty_hr_change_request FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_version_guard();

-- Stable actual-human identity, never names or client-provided actor ids.
CREATE FUNCTION fn_ty_hr_same_human(a bigint,b bigint)RETURNS boolean LANGUAGE sql STABLE SET search_path=''AS $$
 WITH ident AS(SELECT s.id,s.person_id legacy_person_id,CASE WHEN x.account_id IS NOT NULL THEN x.group_id ELSE z.group_id END group_id,CASE WHEN x.account_id IS NOT NULL THEN x.person_id ELSE z.person_id END person_id FROM public.sys_account s LEFT JOIN public.ty_operator_binding x ON x.account_id=s.id LEFT JOIN public.ty_test_account_profile z ON z.account_id=s.id WHERE s.id IN(a,b))
 SELECT a IS NOT NULL AND b IS NOT NULL AND(a=b OR EXISTS(SELECT 1 FROM ident x JOIN ident y ON y.id=b WHERE x.id=a AND((x.person_id IS NOT NULL AND y.person_id=x.person_id AND x.group_id IS NOT NULL AND y.group_id=x.group_id)OR(x.legacy_person_id IS NOT NULL AND x.legacy_person_id=y.legacy_person_id))));$$;
CREATE FUNCTION fn_ty_hr_actor_is_person(a bigint,g bigint,p bigint)RETURNS boolean LANGUAGE sql STABLE SET search_path=''AS $$
 SELECT p IS NOT NULL AND EXISTS(SELECT 1 FROM public.sys_account x LEFT JOIN public.ty_operator_binding b ON b.account_id=x.id LEFT JOIN public.ty_test_account_profile z ON z.account_id=x.id JOIN public.ty_person person ON person.id=p AND person.group_id=g WHERE x.id=a AND(((CASE WHEN b.account_id IS NOT NULL THEN b.person_id ELSE z.person_id END)=p AND(CASE WHEN b.account_id IS NOT NULL THEN b.group_id ELSE z.group_id END)=g)OR(x.person_id IS NOT NULL AND x.person_id=person.legacy_person_id)));$$;

-- Direct SQL is held to the same permanent identity and frozen-intent rules.
CREATE FUNCTION fn_ty_hr_root_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE j jsonb:=to_jsonb(NEW);o jsonb;req public.ty_hr_change_request;emp public.ty_employment;rec public.ty_company;asgn public.ty_position_assignment;
BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='人事历史和核定来源不可删除';END IF;IF TG_OP='UPDATE'THEN o:=to_jsonb(OLD);END IF;
 IF TG_TABLE_NAME='ty_hr_change_request'THEN
  IF TG_OP='INSERT'AND(NEW.status<>'pending'OR NEW.execution_state<>'pending'OR NEW.approved_by IS NOT NULL OR NEW.executed_by IS NOT NULL)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='异动须由原始待核意图开始';END IF;
  IF TG_OP='UPDATE'THEN
   IF(j-ARRAY['status','execution_state','revision','approved_by','executed_by','workflow_instance_id','decision_reason','applied_at','result'])<>(o-ARRAY['status','execution_state','revision','approved_by','executed_by','workflow_instance_id','decision_reason','applied_at','result'])OR NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='人事异动事实意图须冻结并连续更新办理版本';END IF;
   IF OLD.status IN('rejected','cancelled')AND(j-'revision')<>(o-'revision')OR OLD.status='approved'AND NEW.status<>'approved'OR OLD.execution_state='applied'AND(j-'revision')<>(o-'revision')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已处理人事事项不得回退或复用';END IF;
  END IF;
  IF NEW.status IN('approved','rejected')AND(NEW.approved_by IS NULL OR public.fn_ty_hr_same_human(NEW.approved_by,NEW.created_by)OR public.fn_ty_hr_actor_is_person(NEW.approved_by,NEW.group_id,NEW.person_id))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='异动须由非发起人且非本人独立核准';END IF;
  IF NEW.execution_state='applied'AND(NEW.status<>'approved'OR NEW.executed_by IS NULL OR NEW.applied_at IS NULL OR NEW.result IS NULL)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='生效须有已核原意图与实际办理凭据';END IF;
 ELSIF TG_TABLE_NAME='ty_hr_secondment'THEN
  IF TG_OP<>'INSERT'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已核借调事实不可覆盖或删除';END IF;
  SELECT * INTO req FROM public.ty_hr_change_request WHERE id=NEW.request_id;SELECT * INTO emp FROM public.ty_employment WHERE id=NEW.employment_id;
  IF req.id IS NULL OR req.status<>'approved'OR req.action<>'secondment'OR req.person_id<>NEW.person_id OR req.employment_id<>NEW.employment_id OR req.company_id<>NEW.company_id OR req.group_id<>NEW.group_id OR req.approved_by<>NEW.approved_by OR req.created_by<>NEW.created_by OR NEW.valid_from<>req.effective_date OR NEW.valid_to<>(req.payload->>'valid_to')::date OR NEW.receiving_company_id<>(req.payload->>'receiving_company_id')::bigint OR NEW.department_id<>(req.payload->>'department_id')::bigint OR NEW.work_area_id IS DISTINCT FROM(req.payload->>'work_area_id')::bigint OR NEW.cost_basis_ref<>req.payload->>'cost_basis_ref' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='借调须逐项来自确切已核人事申请';END IF;
  IF emp.id IS NULL OR emp.person_id<>NEW.person_id OR emp.group_id<>NEW.group_id OR emp.company_id<>NEW.company_id OR NEW.valid_from<emp.hire_date OR emp.leave_date IS NOT NULL AND NEW.valid_to>emp.leave_date+1 OR NOT EXISTS(SELECT 1 FROM public.ty_company WHERE id=NEW.receiving_company_id AND group_id=NEW.group_id)OR NOT EXISTS(SELECT 1 FROM public.ty_department WHERE id=NEW.department_id AND company_id=NEW.receiving_company_id)OR NEW.work_area_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_work_area WHERE id=NEW.work_area_id AND company_id=NEW.receiving_company_id AND department_id=NEW.department_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='借调来源雇佣、接收组织与期间不一致';END IF;
 ELSIF TG_TABLE_NAME='ty_hr_headcount_plan'THEN
  IF NEW.status IN('published','retired')AND(NEW.published_by IS NULL OR public.fn_ty_hr_same_human(NEW.created_by,NEW.published_by))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='编制发布须独立复核';END IF;
 ELSIF TG_TABLE_NAME='ty_hr_person_profile'THEN
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(NEW.public_values)k(code)WHERE NOT EXISTS(SELECT 1 FROM public.ty_hr_field_catalog f WHERE f.code=k.code AND f.sensitivity='normal')AND NOT EXISTS(SELECT 1 FROM public.ty_hr_field_definition f WHERE f.group_id=NEW.group_id AND f.code=k.code AND f.sensitivity='normal'))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='敏感或未定义的人事资料不得存放公共字段';END IF;
  IF TG_OP='UPDATE'AND(NEW.person_id<>OLD.person_id OR NEW.revision<>OLD.revision+1 OR NEW.private_revision<OLD.private_revision OR NEW.private_revision>OLD.private_revision+1 OR ROW(NEW.private_cipher,NEW.private_iv,NEW.private_tag)IS DISTINCT FROM ROW(OLD.private_cipher,OLD.private_iv,OLD.private_tag)AND NEW.private_revision<>OLD.private_revision+1)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='人员主档与密文更正须连续版本';END IF;
 ELSIF TG_TABLE_NAME='ty_hr_field_definition'THEN
  IF TG_OP='UPDATE'AND(NEW.group_id<>OLD.group_id OR NEW.code<>OLD.code OR NEW.field_type<>OLD.field_type OR NEW.sensitivity<>OLD.sensitivity)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已有扩展字段编码、类型与敏感等级须保留';END IF;
 ELSIF TG_TABLE_NAME='ty_hr_import_preview'THEN
  IF TG_OP='UPDATE'AND OLD.plan_cipher<>'pending'AND((j-ARRAY['status','revision','committed_at'])<>(o-ARRAY['status','revision','committed_at'])OR OLD.status='committed'AND j<>o OR NEW.revision<>OLD.revision+1 OR NEW.status<>'committed'OR NEW.committed_at IS NULL)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='导入预检原件和计划不可改写，另建预检';END IF;
  IF NOT EXISTS(SELECT 1 FROM public.ty_company WHERE id=NEW.company_id AND group_id=NEW.group_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='导入公司与集团不一致';END IF;
 END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_hr_change_root BEFORE INSERT OR UPDATE OR DELETE ON ty_hr_change_request FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_root_guard();
CREATE TRIGGER ty_hr_secondment_root BEFORE INSERT OR UPDATE OR DELETE ON ty_hr_secondment FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_root_guard();
CREATE TRIGGER ty_hr_headcount_root BEFORE INSERT OR UPDATE OR DELETE ON ty_hr_headcount_plan FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_root_guard();
CREATE TRIGGER ty_hr_profile_root BEFORE INSERT OR UPDATE OR DELETE ON ty_hr_person_profile FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_root_guard();
CREATE TRIGGER ty_hr_field_root BEFORE INSERT OR UPDATE OR DELETE ON ty_hr_field_definition FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_root_guard();
CREATE TRIGGER ty_hr_import_root BEFORE INSERT OR UPDATE OR DELETE ON ty_hr_import_preview FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_root_guard();
CREATE FUNCTION fn_ty_hr_import_complete()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE r public.ty_hr_import_preview;BEGIN SELECT * INTO r FROM public.ty_hr_import_preview WHERE id=NEW.id;
 IF r.plan_cipher='pending'OR r.plan_iv='pending'OR r.plan_tag='pending'OR r.source_iv='pending'OR r.source_tag='pending'OR octet_length(r.source_content)NOT BETWEEN 1 AND 3145728 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='导入须原子保存完整加密原件与核对计划';END IF;RETURN NULL;END;$$;
CREATE CONSTRAINT TRIGGER ty_hr_import_complete AFTER INSERT OR UPDATE ON ty_hr_import_preview DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_import_complete();
CREATE FUNCTION fn_ty_hr_employment_keep()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='雇佣历史不可删除';END IF;
 IF TG_OP='UPDATE'AND OLD.status='ended'AND(NEW.status<>'ended'OR NEW.hire_date<>OLD.hire_date OR NEW.leave_date IS DISTINCT FROM OLD.leave_date OR NEW.company_id<>OLD.company_id OR NEW.person_id<>OLD.person_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已结束雇佣不可回退或覆盖，另建更正办理';END IF;
 PERFORM id FROM public.ty_person WHERE id=NEW.person_id FOR UPDATE;
 IF NEW.status<>'cancelled'AND EXISTS(SELECT 1 FROM public.ty_employment x WHERE x.id<>NEW.id AND x.person_id=NEW.person_id AND x.company_id=NEW.company_id AND x.status<>'cancelled'AND daterange(x.hire_date,x.leave_date+1,'[)')&&daterange(NEW.hire_date,NEW.leave_date+1,'[)'))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='同人同公司不能有重叠雇佣';END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_hr_employment_keep BEFORE INSERT OR UPDATE OR DELETE ON ty_employment FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_employment_keep();
DO $$BEGIN IF to_regclass('public.ty_time_plan_segment')IS NOT NULL THEN ALTER TABLE public.ty_time_plan_segment ADD CONSTRAINT ty_time_plan_secondment_fk FOREIGN KEY(secondment_id)REFERENCES public.ty_hr_secondment(id);END IF;END;$$;
-- A used position is a stable role identity. Reassign people explicitly rather
-- than moving the role's historical department/job behind their old records.
CREATE FUNCTION fn_ty_hr_org_identity_keep()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
BEGIN
 IF TG_TABLE_NAME='ty_company_position'THEN
  IF ROW(NEW.group_id,NEW.company_id,NEW.department_id,NEW.job_id)IS DISTINCT FROM ROW(OLD.group_id,OLD.company_id,OLD.department_id,OLD.job_id)AND EXISTS(SELECT 1 FROM public.ty_position_assignment WHERE position_id=OLD.id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已被任职引用的岗位不能改换所属公司、部门或标准岗位，请另建岗位并办理任职调整';END IF;
 ELSIF TG_TABLE_NAME='ty_grade'THEN
  IF NEW.level IS DISTINCT FROM OLD.level AND(EXISTS(SELECT 1 FROM public.ty_position_assignment WHERE grade_id=OLD.id)OR EXISTS(SELECT 1 FROM public.ty_company_position WHERE grade_id=OLD.id))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已使用职级的等级含义须保留，另建职级再调整任职';END IF;
 ELSIF TG_TABLE_NAME='ty_company'THEN
  IF (ROW(NEW.group_id,NEW.ledger_id,NEW.brand_id)IS DISTINCT FROM ROW(OLD.group_id,OLD.ledger_id,OLD.brand_id)OR OLD.org_level IS NOT NULL AND ROW(NEW.org_level,NEW.parent_company_id)IS DISTINCT FROM ROW(OLD.org_level,OLD.parent_company_id))AND EXISTS(SELECT 1 FROM public.ty_employment WHERE company_id=OLD.id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已有雇佣历史的公司不能直接搬换帐套或已核品牌关系，应另建有据组织变更';END IF;
 END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_hr_position_identity BEFORE UPDATE ON ty_company_position FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_org_identity_keep();
CREATE TRIGGER ty_hr_grade_identity BEFORE UPDATE ON ty_grade FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_org_identity_keep();
CREATE TRIGGER ty_hr_company_identity BEFORE UPDATE ON ty_company FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_org_identity_keep();
-- Durable identities include the existing demo portals; this does not grant
-- their roles any new actions or allow the operator UI to create super users.
DO $$DECLARE c record;BEGIN FOR c IN SELECT conname FROM pg_constraint WHERE conrelid='public.ty_operator_binding'::regclass AND contype='c'AND pg_get_constraintdef(oid)LIKE'%profile_code%'LOOP EXECUTE format('ALTER TABLE public.ty_operator_binding DROP CONSTRAINT %I',c.conname);END LOOP;END;$$;
ALTER TABLE ty_operator_binding ADD CONSTRAINT ty_operator_binding_profile_supported CHECK(profile_code IN('config_admin','demo','boss','hr_staff','hr_manager','payroll','recruiter','trainer','store_manager','store_staff','station_staff','group_hr_director','company_hr_director','outsourced_staff','outsource_hr','vendor_contact'));

-- Append to218 after base definitions. Native recruitment/contract/file invariants.
-- These triggers enforce integrity; application current complete-grant checks are still mandatory.
CREATE FUNCTION fn_ty_hr_child_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE j jsonb:=to_jsonb(NEW);o jsonb;rq public.ty_hr_requisition;ca public.ty_hr_candidate;co public.ty_hr_contract;te public.ty_hr_contract_term;em public.ty_employment;fi public.ty_hr_file_asset;pl public.ty_hr_headcount_plan;g bigint;c bigint;p bigint;maker bigint;checker bigint;parent text;allowed boolean;flow_type text;flow_actor bigint;flow_row record;
BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='招聘、合同与来源历史不可删除';END IF;IF TG_OP='UPDATE'THEN o:=to_jsonb(OLD);END IF;
 IF TG_TABLE_NAME='ty_hr_requisition'THEN
  SELECT * INTO pl FROM public.ty_hr_headcount_plan WHERE id=NEW.headcount_plan_id;
  IF pl.id IS NULL OR pl.group_id<>NEW.group_id OR pl.company_id<>NEW.company_id OR pl.department_id IS NOT NULL AND pl.department_id<>NEW.department_id OR pl.position_id IS NOT NULL AND pl.position_id<>NEW.position_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='招聘编制与需求真实范围不一致';END IF;
  IF NEW.status IN('pending','approved')AND(pl.status<>'published'OR NEW.target_on IS NULL OR NOT daterange(pl.valid_from,pl.valid_to,'[)')@>NEW.target_on)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='需求目标日期不在已发布编制内';END IF;
  IF TG_OP='UPDATE'THEN IF(j-ARRAY['title','quantity','target_on','reason','requirements','status','revision','approved_by'])<>(o-ARRAY['title','quantity','target_on','reason','requirements','status','revision','approved_by'])THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='招聘需求稳定范围与岗位不可搬移';END IF;IF OLD.status<>'draft'AND(j-ARRAY['status','revision','approved_by'])<>(o-ARRAY['status','revision','approved_by'])OR OLD.status IN('rejected','closed','cancelled')AND(j-'revision')<>(o-'revision')OR OLD.status='approved'AND NEW.status NOT IN('approved','closed')OR OLD.status='pending'AND NEW.status NOT IN('pending','approved','rejected','cancelled')OR OLD.status='draft'AND NEW.status NOT IN('draft','pending','closed')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='招聘需求须按状态推进且不可改写核准快照';END IF;END IF;
  IF NEW.status='approved'AND NEW.quantity>pl.budget_count THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='招聘核准数量不能超过所选编制';END IF;
  IF NEW.status='approved'AND(NEW.approved_by IS NULL OR public.fn_ty_hr_same_human(NEW.approved_by,NEW.created_by))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='招聘需求须独立核准';END IF;
 ELSIF TG_TABLE_NAME='ty_hr_candidate'THEN
  SELECT * INTO rq FROM public.ty_hr_requisition WHERE id=NEW.requisition_id;
  IF TG_OP='UPDATE'AND(j-ARRAY['status','revision','contact_cipher','contact_iv','contact_tag','contact_revision','resume_file_id','resume_reviewed_by','resume_reviewed_at','resume_review_ref','reviewed_resume_sha256','linked_person_id'])<>(o-ARRAY['status','revision','contact_cipher','contact_iv','contact_tag','contact_revision','resume_file_id','resume_reviewed_by','resume_reviewed_at','resume_review_ref','reviewed_resume_sha256','linked_person_id'])THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='候选来源和招聘归属不可搬移';END IF;
  IF NEW.linked_person_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_person WHERE id=NEW.linked_person_id AND group_id=NEW.group_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='候选关联人员不得跨集团';END IF;
  IF TG_OP='UPDATE'AND OLD.linked_person_id IS NOT NULL AND NEW.linked_person_id IS DISTINCT FROM OLD.linked_person_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='候选明确身份不可改绑';END IF;
  IF rq.id IS NULL OR rq.group_id<>NEW.group_id OR rq.company_id<>NEW.company_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='候选申请不可跨需求公司';END IF;
  IF NEW.linked_person_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_person WHERE id=NEW.linked_person_id AND group_id=NEW.group_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='候选关联人员不可跨集团';END IF;
  IF TG_OP='UPDATE'AND((j-ARRAY['linked_person_id','status','revision','resume_file_id','resume_reviewed_by','resume_reviewed_at','resume_review_ref','reviewed_resume_sha256'])<>(o-ARRAY['linked_person_id','status','revision','resume_file_id','resume_reviewed_by','resume_reviewed_at','resume_review_ref','reviewed_resume_sha256'])AND NOT(OLD.status='new'AND OLD.contact_cipher IS NULL AND NEW.contact_revision=1 AND(j-ARRAY['contact_cipher','contact_iv','contact_tag','contact_revision'])=(o-ARRAY['contact_cipher','contact_iv','contact_tag','contact_revision'])))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='候选身份和原始来源不可随阶段改写';END IF;
  IF TG_OP='UPDATE'AND OLD.linked_person_id IS NOT NULL AND NEW.linked_person_id IS DISTINCT FROM OLD.linked_person_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已确认人员不可改绑';END IF;
  IF NEW.resume_file_id IS NOT NULL THEN SELECT * INTO fi FROM public.ty_hr_file_asset WHERE id=NEW.resume_file_id;IF fi.id IS NULL OR fi.owner_kind<>'candidate'OR fi.owner_id<>NEW.id OR fi.group_id<>NEW.group_id OR fi.company_id<>NEW.company_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='简历附件须精确属于此候选申请';END IF;END IF;
  IF num_nonnulls(NEW.resume_reviewed_by,NEW.resume_reviewed_at,NEW.resume_review_ref,NEW.reviewed_resume_sha256)NOT IN(0,4)OR NEW.resume_reviewed_by IS NOT NULL AND(fi.id IS NULL OR NEW.reviewed_resume_sha256<>fi.sha256 OR length(btrim(NEW.resume_review_ref))<4)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='人工复核须关联当前简历原件SHA及完整证据';END IF;
  IF NEW.status='hired'AND NOT EXISTS(SELECT 1 FROM public.ty_hr_offer WHERE candidate_id=NEW.id AND status='hired'AND resulting_person_id=NEW.linked_person_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='入职状态须有真实Offer入职结果';END IF;
 ELSIF TG_TABLE_NAME='ty_hr_interview'THEN
  SELECT * INTO ca FROM public.ty_hr_candidate WHERE id=NEW.candidate_id;
  IF ca.id IS NULL OR ca.resume_reviewed_by IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='简历人工复核后才能面试';END IF;
  IF public.fn_ty_hr_same_human(NEW.interviewer_id,NEW.created_by)OR public.fn_ty_hr_actor_is_person(NEW.interviewer_id,ca.group_id,ca.linked_person_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='面试结果须由独立面试官核定';END IF;
  IF TG_OP='UPDATE'AND((j-ARRAY['status','score','decision','notes','revision'])<>(o-ARRAY['status','score','decision','notes','revision'])OR OLD.status<>'scheduled'AND(j-'revision')<>(o-'revision')OR OLD.status='scheduled'AND NEW.status NOT IN('scheduled','completed','cancelled'))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='面试安排与已完成结果不可改写';END IF;
  IF NEW.status='completed'AND(NEW.score IS NULL OR NEW.score<0 OR NEW.score>100 OR NEW.decision IS NULL OR NEW.notes IS NULL OR NEW.scheduled_at>clock_timestamp())THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='面试实际完成须有时间、成绩及独立结果';END IF;
 ELSIF TG_TABLE_NAME='ty_hr_offer'THEN
  SELECT * INTO ca FROM public.ty_hr_candidate WHERE id=NEW.candidate_id;
  IF TG_OP='UPDATE'AND(NEW.candidate_id<>OLD.candidate_id OR NEW.version<>OLD.version OR NEW.created_by<>OLD.created_by)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Offer候选与版本身份不可搬移';END IF;
  IF NEW.status IN('pending','approved','sent','accepted','hired')AND coalesce(NEW.terms->>'employment_type','')<>'outsourced'AND NEW.salary_cipher IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='直营Offer须先核定明确薪资，不得缺失默认零';END IF;
  IF TG_OP='UPDATE'AND OLD.status<>'draft'AND((j-ARRAY['status','revision','approved_by','sent_evidence_ref','sent_at','accepted_evidence_ref','accepted_by','accepted_at','resulting_person_id','resulting_employment_id'])<>(o-ARRAY['status','revision','approved_by','sent_evidence_ref','sent_at','accepted_evidence_ref','accepted_by','accepted_at','resulting_person_id','resulting_employment_id']))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Offer条件不可改写，另建新版本';END IF;
  IF TG_OP='UPDATE'AND OLD.status IN('declined','withdrawn','hired')AND(j-'revision')<>(o-'revision')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已结束Offer与真实接受证据不可覆盖';END IF;
  IF TG_OP='UPDATE'AND((OLD.approved_by IS NOT NULL AND NEW.approved_by IS DISTINCT FROM OLD.approved_by)OR(OLD.sent_at IS NOT NULL AND(NEW.sent_at IS DISTINCT FROM OLD.sent_at OR NEW.sent_evidence_ref IS DISTINCT FROM OLD.sent_evidence_ref))OR(OLD.accepted_at IS NOT NULL AND(NEW.accepted_at IS DISTINCT FROM OLD.accepted_at OR NEW.accepted_by IS DISTINCT FROM OLD.accepted_by OR NEW.accepted_evidence_ref IS DISTINCT FROM OLD.accepted_evidence_ref)))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Offer已发生核准送达接受事实不得改写';END IF;
  IF TG_OP='UPDATE'AND((OLD.status='draft'AND NEW.status NOT IN('draft','pending','withdrawn'))OR(OLD.status='pending'AND NEW.status NOT IN('pending','approved','declined','withdrawn'))OR(OLD.status='approved'AND NEW.status NOT IN('approved','sent','withdrawn'))OR(OLD.status='sent'AND NEW.status NOT IN('sent','accepted','declined','withdrawn'))OR(OLD.status='accepted'AND NEW.status NOT IN('accepted','hired','withdrawn'))OR(OLD.status IN('hired','withdrawn','declined')AND(j-'revision')<>(o-'revision')))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Offer状态不得跨步或回退';END IF;
  IF NEW.status IN('approved','sent','accepted','hired')AND(NEW.approved_by IS NULL OR public.fn_ty_hr_same_human(NEW.approved_by,NEW.created_by)OR public.fn_ty_hr_actor_is_person(NEW.approved_by,ca.group_id,ca.linked_person_id))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Offer须独立核准，不能本人或代理本人核准';END IF;
  IF NEW.status IN('sent','accepted','hired')AND(NEW.sent_at IS NULL OR length(btrim(coalesce(NEW.sent_evidence_ref,'')))<4)OR NEW.status IN('accepted','hired')AND(NEW.accepted_by IS NULL OR NEW.accepted_at IS NULL OR length(btrim(coalesce(NEW.accepted_evidence_ref,'')))<4)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Offer送达和接受分别保留真实证据';END IF;
  IF NEW.status='approved'AND(TG_OP='INSERT'OR o->>'status'<>'approved')THEN SELECT * INTO rq FROM public.ty_hr_requisition WHERE id=ca.requisition_id FOR UPDATE;IF rq.status<>'approved'OR(SELECT count(*)FROM public.ty_hr_offer x JOIN public.ty_hr_candidate y ON y.id=x.candidate_id WHERE y.requisition_id=rq.id AND x.id<>NEW.id AND x.status IN('approved','sent','accepted','hired'))>=rq.quantity THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Offer核准须在需求已核真实名额内';END IF;END IF;
  IF NEW.status='hired'THEN SELECT * INTO em FROM public.ty_employment WHERE id=NEW.resulting_employment_id;IF em.id IS NULL OR em.person_id<>NEW.resulting_person_id OR em.group_id<>ca.group_id OR em.company_id<>ca.company_id OR em.hire_date<>NEW.starts_on OR ca.linked_person_id IS NOT NULL AND ca.linked_person_id<>em.person_id OR lower(em.employment_type)~'(outsource|agency|vendor|派遣|外包)'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Offer入职须关联同人同公司的真实直营雇佣';END IF;END IF;
 ELSIF TG_TABLE_NAME='ty_hr_contract'THEN
  SELECT * INTO em FROM public.ty_employment WHERE id=NEW.employment_id;
  IF TG_OP='UPDATE'AND(j-ARRAY['title','starts_on','ends_on','content','source_hash','status','revision','signed_on','signed_by','evidence_file_id','terminated_on','termination_ref','terminated_by'])<>(o-ARRAY['title','starts_on','ends_on','content','source_hash','status','revision','signed_on','signed_by','evidence_file_id','terminated_on','termination_ref','terminated_by'])THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='合同永久身份、法律主体、版本链不可搬移';END IF;
  IF NOT EXISTS(SELECT 1 FROM public.ty_company WHERE id=NEW.legal_entity_company_id AND group_id=NEW.group_id)OR lower(em.employment_type)~'(outsource|agency|vendor|派遣|外包)'OR EXISTS(SELECT 1 FROM public.ty_outsource_engagement WHERE employment_id=em.id AND status<>'cancelled'AND daterange(valid_from,valid_to,'[)')@>NEW.starts_on)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='劳动合同法律主体或直营用工关系不符';END IF;
  IF NEW.starts_on<em.hire_date THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='劳动合同履行起点不能早于该真实雇佣';END IF;
  IF NEW.parent_contract_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_hr_contract x WHERE x.id=NEW.parent_contract_id AND x.group_id=NEW.group_id AND x.company_id=NEW.company_id AND x.person_id=NEW.person_id AND x.employment_id=NEW.employment_id AND x.code=NEW.code AND x.parent_key=NEW.parent_key AND x.version+1=NEW.version AND x.status IN('signed','terminated'))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='合同版本须沿同人同雇佣同编号链';END IF;
  IF NEW.status IN('signed','terminated')AND(NEW.signed_on>public.app_today()OR em.legal_subject_name IS NULL OR NOT EXISTS(SELECT 1 FROM public.ty_company WHERE id=NEW.legal_entity_company_id AND em.legal_subject_name IN(name,legal_name)))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='签署登记须核定真实雇主且日期不能在未来';END IF;
  IF NEW.status IN('signed','terminated')THEN SELECT * INTO fi FROM public.ty_hr_file_asset WHERE id=NEW.evidence_file_id;IF fi.id IS NULL OR fi.owner_kind<>'contract'OR fi.owner_id<>NEW.id OR fi.group_id<>NEW.group_id OR fi.company_id<>NEW.company_id OR fi.person_id<>NEW.person_id OR public.fn_ty_hr_same_human(NEW.signed_by,NEW.created_by)OR public.fn_ty_hr_actor_is_person(NEW.signed_by,NEW.group_id,NEW.person_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='签署登记须关联本人合同原件与独立核验人';END IF;END IF;
 ELSIF TG_TABLE_NAME='ty_hr_contract_term'THEN
  SELECT * INTO co FROM public.ty_hr_contract WHERE id=NEW.contract_id;SELECT * INTO em FROM public.ty_employment WHERE id=co.employment_id;
  IF NEW.parent_key<>'hr-term:'||co.employment_id::text||':'||NEW.term_code OR NEW.valid_from<co.starts_on OR co.ends_on IS NOT NULL AND(NEW.valid_to IS NULL OR NEW.valid_to>co.ends_on+1)OR lower(em.employment_type)~'(outsource|agency|vendor|派遣|外包)'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='条款父义务、用工关系和合同区间须真实一致';END IF;
  IF NEW.term_kind IN('salary','bonus')AND NEW.amount IS NULL OR NEW.term_kind IN('salary','attendance','job')AND NEW.value->>'semantics'<>'parameter'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='标准参数不得伪造额外应付，薪资金额不得缺失';END IF;
  IF NEW.status IN('reviewed','effective','ended')AND(co.status NOT IN('signed','terminated')OR NEW.reviewed_by IS NULL OR public.fn_ty_hr_same_human(NEW.reviewed_by,NEW.created_by)OR public.fn_ty_hr_actor_is_person(NEW.reviewed_by,co.group_id,co.person_id))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='条款须已签合同与独立核准';END IF;
  IF NEW.status='effective'AND(co.status<>'signed'OR NEW.applied_by IS NULL OR NOT EXISTS(SELECT 1 FROM public.ty_hr_contract_term_period WHERE term_id=NEW.id AND status='active'))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='生效条款须有真实采用片段';END IF;
 ELSIF TG_TABLE_NAME='ty_hr_contract_term_period'THEN
  SELECT * INTO te FROM public.ty_hr_contract_term WHERE id=NEW.term_id;SELECT * INTO co FROM public.ty_hr_contract WHERE id=te.contract_id;IF TG_OP='INSERT'AND co.status<>'signed'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='终止合同不可新造生效片段';END IF;
  IF NEW.source_contract_id<>te.contract_id OR NEW.parent_key<>te.parent_key OR NEW.valid_from<te.valid_from OR te.valid_to IS NOT NULL AND(NEW.valid_to IS NULL OR NEW.valid_to>te.valid_to)OR te.reviewed_by IS NULL OR co.status NOT IN('signed','terminated')OR public.fn_ty_hr_same_human(NEW.activated_by,te.created_by)OR public.fn_ty_hr_actor_is_person(NEW.activated_by,co.group_id,co.person_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='条款生效片段必须源于已核同一条款';END IF;
  IF TG_OP='UPDATE'THEN
   IF(j-ARRAY['valid_to','ended_by','status','cancellation_ref'])<>(o-ARRAY['valid_to','ended_by','status','cancellation_ref'])OR OLD.ended_by IS NOT NULL AND j<>o OR OLD.status='cancelled'AND j<>o OR NEW.valid_to IS NULL AND OLD.valid_to IS NOT NULL OR NEW.valid_to IS NOT NULL AND OLD.valid_to IS NOT NULL AND NEW.valid_to>OLD.valid_to OR NEW.ended_by IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='实际生效区间只允许一次收窄或取消，不可搬移和延长';END IF;
   IF public.fn_ty_hr_same_human(NEW.ended_by,te.created_by)OR public.fn_ty_hr_actor_is_person(NEW.ended_by,co.group_id,co.person_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='本人不可终止或替代本人的工资参数';END IF;
   IF NEW.status='cancelled'AND(OLD.valid_from<public.app_today()OR length(btrim(coalesce(NEW.cancellation_ref,'')))<4)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已开始片段不能抹除，未来取消须保留依据';END IF;
  END IF;
 ELSIF TG_TABLE_NAME='ty_hr_file_asset'THEN
  IF NEW.owner_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='附件必须有真实业务归属';END IF;
  IF NEW.owner_kind='candidate'THEN SELECT * INTO ca FROM public.ty_hr_candidate WHERE id=NEW.owner_id;g:=ca.group_id;c:=ca.company_id;p:=ca.linked_person_id;
  ELSIF NEW.owner_kind='contract'THEN SELECT * INTO co FROM public.ty_hr_contract WHERE id=NEW.owner_id;g:=co.group_id;c:=co.company_id;p:=co.person_id;
  ELSIF NEW.owner_kind='person'THEN SELECT group_id,id INTO g,p FROM public.ty_person WHERE id=NEW.owner_id;c:=NEW.company_id;
  ELSE RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='此多态附件归属尚未开放';END IF;
  IF g IS NULL OR g<>NEW.group_id OR c IS DISTINCT FROM NEW.company_id OR p IS DISTINCT FROM NEW.person_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='附件集团、公司、人员与业务归属不一致';END IF;
  IF NEW.sha256!~'^[0-9a-f]{64}$'OR NEW.sensitivity<>'restricted'OR NEW.storage_encoding<>'aes256gcm'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='受控附件须存储原SHA和加密原字节';END IF;
 END IF;
 -- A bound domain transition must possess its exact real workflow receipt, including SQL callers.
 IF TG_OP='UPDATE'AND j->>'status'IS DISTINCT FROM o->>'status'AND to_regclass('public.ty_hr_record_proposal')IS NOT NULL THEN
  flow_type:=CASE WHEN TG_TABLE_NAME='ty_hr_requisition'AND NEW.status IN('approved','rejected')THEN 'hr_requisition'WHEN TG_TABLE_NAME='ty_hr_offer'AND OLD.status='pending'AND NEW.status IN('approved','declined')THEN 'hr_offer'WHEN TG_TABLE_NAME='ty_hr_contract'AND NEW.status='signed'THEN 'hr_contract_sign'WHEN TG_TABLE_NAME='ty_hr_contract_term'AND NEW.status='reviewed'THEN 'hr_contract_term'ELSE NULL END;
  IF flow_type IS NOT NULL THEN
   IF TG_TABLE_NAME='ty_hr_requisition'THEN g:=NEW.group_id;c:=NEW.company_id;flow_actor:=NEW.approved_by;
   ELSIF TG_TABLE_NAME='ty_hr_offer'THEN SELECT group_id,company_id INTO g,c FROM public.ty_hr_candidate WHERE id=NEW.candidate_id;flow_actor:=NEW.approved_by;
   ELSIF TG_TABLE_NAME='ty_hr_contract'THEN g:=NEW.group_id;c:=NEW.company_id;flow_actor:=NEW.signed_by;
   ELSE SELECT group_id,company_id INTO g,c FROM public.ty_hr_contract WHERE id=NEW.contract_id;flow_actor:=NEW.reviewed_by;END IF;
   IF EXISTS(SELECT 1 FROM public.ty_workflow_binding WHERE business_type=flow_type AND group_id=g AND(company_id IS NULL OR company_id=c)AND status='active'AND valid_from<=now()AND(valid_to IS NULL OR now()<valid_to))OR EXISTS(SELECT 1 FROM public.ty_hr_record_proposal WHERE business_type=flow_type AND entity_id=NEW.id AND status IN('pending','blocked'))THEN
    SELECT p.*,i.status flow_status,i.last_approver_id INTO flow_row FROM public.ty_hr_record_proposal p JOIN public.ty_workflow_instance i ON i.id=p.workflow_instance_id WHERE p.business_type=flow_type AND p.entity_id=NEW.id AND p.entity_revision=OLD.revision AND p.entity_db_fingerprint=md5(to_jsonb(OLD)::text)AND p.status='pending'AND i.subject_type=p.business_type AND i.subject_id=p.id AND i.source_hash=p.payload_hash AND i.last_approver_id=flow_actor AND i.status=CASE WHEN NEW.status IN('rejected','declined')THEN 'rejected'ELSE 'approved'END ORDER BY p.id DESC LIMIT 1;
    IF flow_row.id IS NULL OR public.fn_ty_hr_same_human(flow_actor,flow_row.created_by)OR public.fn_ty_hr_same_human(flow_actor,flow_row.original_created_by)OR public.fn_ty_hr_actor_is_person(flow_actor,g,flow_row.person_id)OR NOT EXISTS(SELECT 1 FROM public.ty_workflow_task WHERE instance_id=flow_row.workflow_instance_id AND approver_id=flow_actor AND status=CASE WHEN NEW.status IN('rejected','declined')THEN 'rejected'ELSE 'approved'END AND acted_at IS NOT NULL)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='绑定业务不得绕过确切独立审批节点与冻结来源版本';END IF;
   END IF;
  END IF;
 END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_hr_requisition_child BEFORE INSERT OR UPDATE OR DELETE ON ty_hr_requisition FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_child_guard();
CREATE TRIGGER ty_hr_candidate_child BEFORE INSERT OR UPDATE OR DELETE ON ty_hr_candidate FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_child_guard();
CREATE TRIGGER ty_hr_interview_child BEFORE INSERT OR UPDATE OR DELETE ON ty_hr_interview FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_child_guard();
CREATE TRIGGER ty_hr_offer_child BEFORE INSERT OR UPDATE OR DELETE ON ty_hr_offer FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_child_guard();
CREATE TRIGGER ty_hr_contract_child BEFORE INSERT OR UPDATE OR DELETE ON ty_hr_contract FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_child_guard();
CREATE TRIGGER ty_hr_contract_term_child BEFORE INSERT OR UPDATE OR DELETE ON ty_hr_contract_term FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_child_guard();
CREATE TRIGGER ty_hr_contract_period_child BEFORE INSERT OR UPDATE OR DELETE ON ty_hr_contract_term_period FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_child_guard();
CREATE TRIGGER ty_hr_file_child BEFORE INSERT OR UPDATE OR DELETE ON ty_hr_file_asset FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_child_guard();

-- Typed protected business intents. Generic workflow stores references, not documents or salary.
CREATE TABLE ty_hr_record_proposal(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),person_id bigint REFERENCES ty_person(id),employment_id bigint REFERENCES ty_employment(id),
 business_type text NOT NULL CHECK(business_type IN('hr_requisition','hr_offer','hr_contract_sign','hr_contract_term')),
 entity_id bigint NOT NULL,entity_revision integer NOT NULL CHECK(entity_revision>0),original_created_by bigint NOT NULL REFERENCES sys_account(id),
 entity_db_fingerprint text NOT NULL CHECK(entity_db_fingerprint~'^[0-9a-f]{32}$'),payload_hash text NOT NULL,payload_cipher text NOT NULL,payload_iv text NOT NULL,payload_tag text NOT NULL,
 status text NOT NULL DEFAULT 'pending'CHECK(status IN('pending','applied','rejected','cancelled','blocked')),
 created_by bigint NOT NULL REFERENCES sys_account(id),workflow_instance_id bigint REFERENCES ty_workflow_instance(id),receipt_id bigint REFERENCES ty_workflow_instance(id),
 approved_by bigint REFERENCES sys_account(id),executed_by bigint REFERENCES sys_account(id),cancelled_by bigint REFERENCES sys_account(id),applied_entity_hash text,result jsonb,
 revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),applied_at timestamptz,
 FOREIGN KEY(company_id,group_id)REFERENCES ty_company(id,group_id),FOREIGN KEY(person_id,group_id)REFERENCES ty_person(id,group_id),
 FOREIGN KEY(employment_id,company_id,group_id)REFERENCES ty_employment(id,company_id,group_id)
);
CREATE UNIQUE INDEX ty_hr_record_one_active ON ty_hr_record_proposal(business_type,entity_id)WHERE status IN('pending','blocked');
CREATE FUNCTION fn_ty_hr_record_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE j jsonb:=to_jsonb(NEW);old_json jsonb;inst public.ty_workflow_instance;g bigint;c bigint;p bigint;e bigint;maker bigint;source_revision integer;source_status text;source_actor bigint;source_hash text;
BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='业务审批提案与凭证不得删除';END IF;
 IF NEW.business_type='hr_requisition'THEN SELECT group_id,company_id,NULL::bigint,NULL::bigint,created_by,revision,status,approved_by,NULL::text INTO g,c,p,e,maker,source_revision,source_status,source_actor,source_hash FROM public.ty_hr_requisition WHERE id=NEW.entity_id;
 ELSIF NEW.business_type='hr_offer'THEN SELECT ca.group_id,ca.company_id,ca.linked_person_id,NULL::bigint,o.created_by,o.revision,o.status,o.approved_by,o.source_hash INTO g,c,p,e,maker,source_revision,source_status,source_actor,source_hash FROM public.ty_hr_offer o JOIN public.ty_hr_candidate ca ON ca.id=o.candidate_id WHERE o.id=NEW.entity_id;
 ELSIF NEW.business_type='hr_contract_sign'THEN SELECT group_id,company_id,person_id,employment_id,created_by,revision,status,signed_by,ty_hr_contract.source_hash INTO g,c,p,e,maker,source_revision,source_status,source_actor,source_hash FROM public.ty_hr_contract WHERE id=NEW.entity_id;
 ELSE SELECT co.group_id,co.company_id,co.person_id,co.employment_id,te.created_by,te.revision,te.status,te.reviewed_by,te.source_hash INTO g,c,p,e,maker,source_revision,source_status,source_actor,source_hash FROM public.ty_hr_contract_term te JOIN public.ty_hr_contract co ON co.id=te.contract_id WHERE te.id=NEW.entity_id;END IF;
 IF g IS NULL OR NEW.group_id<>g OR NEW.company_id<>c OR NEW.person_id IS DISTINCT FROM p OR NEW.employment_id IS DISTINCT FROM e OR NEW.original_created_by<>maker THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='业务审批提案与原始业务范围或经办不符';END IF;
 IF TG_OP='INSERT'AND(NEW.status<>'pending'OR NEW.workflow_instance_id IS NOT NULL OR NEW.receipt_id IS NOT NULL OR NEW.approved_by IS NOT NULL OR NEW.executed_by IS NOT NULL OR NEW.cancelled_by IS NOT NULL OR NEW.result IS NOT NULL OR NEW.applied_entity_hash IS NOT NULL OR NEW.entity_revision<>source_revision OR(NEW.business_type IN('hr_requisition','hr_offer')AND source_status<>'pending')OR(NEW.business_type IN('hr_contract_sign','hr_contract_term')AND source_status<>'draft'))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='审批提案必须从当前真实待核业务创建，不得预造结果';END IF;
 IF TG_OP='UPDATE'AND(OLD.status='blocked'AND NEW.status NOT IN('blocked','cancelled')OR OLD.status='pending'AND NEW.status NOT IN('pending','blocked','applied','rejected','cancelled'))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='审批意图不能回退或复用';END IF;
 IF TG_OP='UPDATE'THEN old_json:=to_jsonb(OLD);IF(j-ARRAY['status','workflow_instance_id','receipt_id','approved_by','executed_by','cancelled_by','applied_entity_hash','result','revision','applied_at'])<>(old_json-ARRAY['status','workflow_instance_id','receipt_id','approved_by','executed_by','cancelled_by','applied_entity_hash','result','revision','applied_at'])OR OLD.status IN('applied','rejected','cancelled')AND(j-'revision')<>(old_json-'revision')OR OLD.workflow_instance_id IS NOT NULL AND NEW.workflow_instance_id IS DISTINCT FROM OLD.workflow_instance_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已提交审批意图和确切凭证不能覆盖';END IF;END IF;
 IF NEW.workflow_instance_id IS NOT NULL THEN SELECT * INTO inst FROM public.ty_workflow_instance WHERE id=NEW.workflow_instance_id;IF inst.id IS NULL OR inst.subject_type<>NEW.business_type OR inst.subject_id<>NEW.id OR inst.group_id<>NEW.group_id OR inst.company_id IS DISTINCT FROM NEW.company_id OR inst.applicant_id<>NEW.created_by OR inst.source_hash<>NEW.payload_hash THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='审批实例必须与本次业务冻结意图确切一致';END IF;END IF;
 IF NEW.status='applied'THEN IF NEW.receipt_id IS NULL OR NEW.receipt_id IS DISTINCT FROM NEW.workflow_instance_id OR inst.status<>'approved'OR NEW.executed_by IS NULL OR NEW.approved_by IS DISTINCT FROM inst.last_approver_id OR public.fn_ty_hr_same_human(NEW.approved_by,NEW.created_by)OR public.fn_ty_hr_same_human(NEW.approved_by,NEW.original_created_by)OR public.fn_ty_hr_actor_is_person(NEW.approved_by,NEW.group_id,NEW.person_id)OR source_actor IS DISTINCT FROM NEW.approved_by OR source_status<>(CASE WHEN NEW.business_type='hr_contract_sign'THEN 'signed'WHEN NEW.business_type='hr_contract_term'THEN 'reviewed'ELSE 'approved'END) OR NEW.applied_entity_hash IS DISTINCT FROM source_hash OR NOT EXISTS(SELECT 1 FROM public.ty_workflow_task WHERE instance_id=inst.id AND approver_id=NEW.approved_by AND status='approved'AND acted_at IS NOT NULL)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='业务实际办理须真实独立审批人与当前执行人及确切凭证';END IF;END IF;
 IF NEW.status='rejected'AND(inst.id IS NULL OR inst.status<>'rejected'OR NEW.approved_by IS NULL OR public.fn_ty_hr_same_human(NEW.approved_by,NEW.created_by)OR public.fn_ty_hr_same_human(NEW.approved_by,NEW.original_created_by)OR public.fn_ty_hr_actor_is_person(NEW.approved_by,NEW.group_id,NEW.person_id)OR NOT EXISTS(SELECT 1 FROM public.ty_workflow_task WHERE instance_id=inst.id AND approver_id=NEW.approved_by AND status='rejected'AND acted_at IS NOT NULL))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='驳回须真实独立审批节点';END IF;
 IF NEW.status='cancelled'AND(inst.id IS NULL OR inst.status NOT IN('running','blocked','cancelled')OR NEW.cancelled_by IS NULL OR NOT public.fn_ty_hr_same_human(NEW.cancelled_by,NEW.created_by))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='撤回须真实本次提交人和未生效流程';END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_hr_record_keep BEFORE INSERT OR UPDATE OR DELETE ON ty_hr_record_proposal FOR EACH ROW EXECUTE FUNCTION fn_ty_hr_record_guard();
